trazabilidad_archivos.codigo_final:
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
}

img {
  display: block;
  max-width: 100%;
}

:root {
  --color-primary: #0057A8;
  --color-secondary: #00AEEF;
  --color-accent: #FF6B00;
  --color-bg: #F4F7FB;
  --color-surface: #FFFFFF;
  --color-text-primary: #1A1A2E;
  --color-text-secondary: #4A5568;
  --color-border: #E2E8F0;

  --font-family-base: system-ui, -apple-system, 'Segoe UI', Arial, sans-serif;

  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2.5rem;
  --spacing-xl: 4rem;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;

  --shadow-card: 0 4px 16px rgba(0, 87, 168, 0.10);
  --shadow-btn-hover: 0 6px 20px rgba(0, 87, 168, 0.22);

  --transition-base: 200ms ease-in-out;
}

body {
  font-family: var(--font-family-base);
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.site-header {
  background-color: var(--color-primary);
  padding: var(--spacing-sm) var(--spacing-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.site-header__logo {
  color: var(--color-surface);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.main-container {
  max-width: 860px;
  margin: 0 auto;
  padding: var(--spacing-lg) var(--spacing-sm);
  flex: 1;
}

.page-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.page-title__heading {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  color: var(--color-primary);
  font-weight: 700;
  margin: 0 0 var(--spacing-xs) 0;
}

.page-title__subtitle {
  font-size: 1rem;
  color: var(--color-text-secondary);
  margin: 0;
}

.country-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-lg);
}

.country-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-xs);
  padding: var(--spacing-sm) var(--spacing-xs);
  background-color: var(--color-surface);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  font-family: var(--font-family-base);
  font-size: 0.875rem;
  color: var(--color-text-primary);
  box-shadow: var(--shadow-card);
  transition: border-color var(--transition-base),
              box-shadow var(--transition-base),
              transform var(--transition-base);
}

.country-btn:hover {
  border-color: var(--color-secondary);
  box-shadow: var(--shadow-btn-hover);
  transform: translateY(-2px);
}

.country-btn.is-active {
  border-color: var(--color-primary);
  background-color: #EBF4FF;
  color: var(--color-primary);
  font-weight: 600;
}

.country-btn__flag {
  font-size: 2rem;
  line-height: 1;
}

.country-btn__label {
  text-align: center;
  line-height: 1.2;
}

.greeting-display {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: var(--spacing-lg) var(--spacing-md);
  text-align: center;
  border: 1px solid var(--color-border);
  transition: opacity var(--transition-base);
}

.greeting-display.is-hidden {
  opacity: 0;
  pointer-events: none;
}

.greeting-display__flag {
  font-size: 4rem;
  line-height: 1;
  margin-bottom: var(--spacing-sm);
}

.greeting-display__text {
  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
  font-weight: 700;
  color: var(--color-primary);
  margin: 0 0 var(--spacing-xs) 0;
}

.greeting-display__country {
  font-size: 1rem;
  color: var(--color-text-secondary);
  margin: 0;
}

.site-footer {
  background-color: var(--color-primary);
  color: var(--color-surface);
  text-align: center;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 0.875rem;
  opacity: 0.92;
}

@media (max-width: 600px) {
  .site-header {
    padding: var(--spacing-sm);
  }

  .country-grid {
    grid-template-columns: repeat(auto-fill, minmax(90px, 1fr));
  }

  .greeting-display {
    padding: var(--spacing-md) var(--spacing-sm);
  }
}
